-- =====================================================================
-- RedFit — Modelagem de Banco de Dados — Script completo (MySQL 8.0.16+)
-- REQUER MySQL >= 8.0.16 (CHECK aplicado). Collation utf8mb4_0900_ai_ci.
-- Não compatível com MariaDB.
--
-- FONTE DA VERDADE DO MODELO LÓGICO (unificação v3 — 06/11/2026):
--   * Este script define nomes de colunas, tipos e restrições.
--   * Sem generalização FUNCIONARIO (GERENTE, RECEPCIONISTA, INSTRUTOR separados).
--   * Sem tabela CONTRATO/MATRICULA: vínculo em ALUNO (ID_PLANO + DT_CONTRATACAO).
--   * Sem tabela TREINO_ALTERACAO: auditoria em TREINO (ID_INSTRUTOR_ALTEROU, DT_ALTERACAO).
--   * Sem boleto: TP_FORMA IN ('PIX','DEBITO','CREDITO').
--
-- NÚMEROS DE NEGÓCIO CONGELADOS (alinhados ao README / RN19):
--   * Rede: 23 unidades | Unidade estudada: Neo Química Arena
--   * Equipe unidade 1: 2 gerentes, 2 recepcionistas, 4 instrutores
--   * Planos: RED (R$ 9,90 1º mês / R$ 139,90), ANUAL (R$ 89,90 + matr. R$ 49,90),
--            FIT (R$ 119,90 + matr. R$ 49,90)
--   * Massa sintética reduzida (não é o volume real da unidade)
-- =====================================================================

DROP DATABASE IF EXISTS redfit;
CREATE DATABASE redfit CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE redfit;

-- ---------------------------------------------------------------------
-- 1. UNIDADE
-- ---------------------------------------------------------------------
CREATE TABLE UNIDADE (
  ID_UNIDADE      INT AUTO_INCREMENT PRIMARY KEY,
  NM_UNIDADE      VARCHAR(100) NOT NULL,
  DS_LOGRADOURO   VARCHAR(150) NOT NULL,
  NR_ENDERECO     VARCHAR(10)  NOT NULL,
  DS_COMPLEMENTO  VARCHAR(60)  NULL,
  NM_BAIRRO       VARCHAR(80)  NOT NULL,
  NR_CEP          CHAR(8)      NOT NULL,
  NM_CIDADE       VARCHAR(80)  NOT NULL,
  SG_UF           CHAR(2)      NOT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_UNIDADE_CEP CHECK (NR_CEP REGEXP '^[0-9]{8}$')
);

-- ---------------------------------------------------------------------
-- 2. FUNCIONÁRIOS (sem generalização)
-- ---------------------------------------------------------------------
CREATE TABLE GERENTE (
  ID_GERENTE      INT AUTO_INCREMENT PRIMARY KEY,
  NM_GERENTE      VARCHAR(120) NOT NULL,
  NR_CPF          CHAR(11)     NOT NULL UNIQUE,
  NR_TELEFONE     VARCHAR(11)  NOT NULL,
  DS_EMAIL        VARCHAR(120) NULL,
  DS_LOGRADOURO   VARCHAR(150) NULL,
  NR_ENDERECO     VARCHAR(10)  NULL,
  DS_COMPLEMENTO  VARCHAR(60)  NULL,
  NM_BAIRRO       VARCHAR(80)  NULL,
  NR_CEP          CHAR(8)      NULL,
  NM_CIDADE       VARCHAR(80)  NULL,
  SG_UF           CHAR(2)      NULL,
  ID_UNIDADE      INT          NOT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_GERENTE_CPF CHECK (NR_CPF REGEXP '^[0-9]{11}$'),
  CONSTRAINT CK_GERENTE_TEL CHECK (CHAR_LENGTH(NR_TELEFONE) IN (10,11)),
  CONSTRAINT FK_GERENTE_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT
);

CREATE TABLE RECEPCIONISTA (
  ID_RECEPCIONISTA INT AUTO_INCREMENT PRIMARY KEY,
  NM_RECEPCIONISTA VARCHAR(120) NOT NULL,
  NR_CPF           CHAR(11)     NOT NULL UNIQUE,
  NR_TELEFONE      VARCHAR(11)  NOT NULL,
  DS_EMAIL         VARCHAR(120) NULL,
  DS_LOGRADOURO    VARCHAR(150) NULL,
  NR_ENDERECO      VARCHAR(10)  NULL,
  DS_COMPLEMENTO   VARCHAR(60)  NULL,
  NM_BAIRRO        VARCHAR(80)  NULL,
  NR_CEP           CHAR(8)      NULL,
  NM_CIDADE        VARCHAR(80)  NULL,
  SG_UF            CHAR(2)      NULL,
  ID_UNIDADE       INT          NOT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_RECEP_CPF CHECK (NR_CPF REGEXP '^[0-9]{11}$'),
  CONSTRAINT CK_RECEP_TEL CHECK (CHAR_LENGTH(NR_TELEFONE) IN (10,11)),
  CONSTRAINT FK_RECEP_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT
);

CREATE TABLE INSTRUTOR (
  ID_INSTRUTOR     INT AUTO_INCREMENT PRIMARY KEY,
  NM_INSTRUTOR     VARCHAR(120) NOT NULL,
  NR_CPF           CHAR(11)     NOT NULL UNIQUE,
  NR_TELEFONE      VARCHAR(11)  NOT NULL,
  DS_EMAIL         VARCHAR(120) NULL,
  NR_CREF          VARCHAR(20)  NOT NULL UNIQUE,
  DS_ESPECIALIDADE VARCHAR(100) NULL,
  DS_CERTIFICACAO  VARCHAR(150) NULL,
  NM_INSTITUICAO   VARCHAR(150) NULL,
  NR_ANO_FORMACAO  SMALLINT     NULL,
  DS_DIPLOMA       VARCHAR(150) NULL,
  DS_LOGRADOURO    VARCHAR(150) NULL,
  NR_ENDERECO      VARCHAR(10)  NULL,
  DS_COMPLEMENTO   VARCHAR(60)  NULL,
  NM_BAIRRO        VARCHAR(80)  NULL,
  NR_CEP           CHAR(8)      NULL,
  NM_CIDADE        VARCHAR(80)  NULL,
  SG_UF            CHAR(2)      NULL,
  ID_UNIDADE       INT          NOT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_INSTR_CPF CHECK (NR_CPF REGEXP '^[0-9]{11}$'),
  CONSTRAINT CK_INSTR_TEL CHECK (CHAR_LENGTH(NR_TELEFONE) IN (10,11)),
  CONSTRAINT FK_INSTR_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 3. PLANO
-- ---------------------------------------------------------------------
CREATE TABLE PLANO (
  ID_PLANO             INT AUTO_INCREMENT PRIMARY KEY,
  NM_PLANO             VARCHAR(50)   NOT NULL UNIQUE,
  DS_ABRANGENCIA       VARCHAR(100)  NOT NULL,
  VL_MENSAL            DECIMAL(10,2) NOT NULL,
  VL_PRIMEIRO_MES      DECIMAL(10,2) NULL,
  VL_MATRICULA         DECIMAL(10,2) NOT NULL DEFAULT 0,
  IN_FIDELIDADE        TINYINT(1)    NOT NULL DEFAULT 0,
  QT_MESES_FIDELIDADE  TINYINT       NOT NULL DEFAULT 0,
  PC_MULTA             DECIMAL(5,2)  NULL,
  QT_AMIGOS            TINYINT       NOT NULL DEFAULT 0,
  IN_RENOVACAO_AUTO    TINYINT(1)    NOT NULL DEFAULT 1,
  IN_BLOQUEIA_ATRASO   TINYINT(1)    NOT NULL DEFAULT 0,
  DS_PLANO             VARCHAR(255)  NULL,
  IN_ATIVO             TINYINT(1)    NOT NULL DEFAULT 1,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_PLANO_VALORES CHECK (VL_MENSAL > 0 AND VL_MATRICULA >= 0),
  CONSTRAINT CK_PLANO_FIDEL   CHECK (IN_FIDELIDADE IN (0,1)
                                     AND (IN_FIDELIDADE = 1 OR QT_MESES_FIDELIDADE = 0)),
  CONSTRAINT CK_PLANO_MULTA   CHECK (PC_MULTA IS NULL OR PC_MULTA BETWEEN 0 AND 100)
);

-- ---------------------------------------------------------------------
-- 4. ALUNO
-- ---------------------------------------------------------------------
CREATE TABLE ALUNO (
  ID_ALUNO         INT AUTO_INCREMENT PRIMARY KEY,
  NM_ALUNO         VARCHAR(120) NOT NULL,
  NR_CPF           CHAR(11)     NOT NULL UNIQUE,
  DT_NASCIMENTO    DATE         NOT NULL,
  DS_LOGRADOURO    VARCHAR(150) NOT NULL,
  NR_ENDERECO      VARCHAR(10)  NOT NULL,
  DS_COMPLEMENTO   VARCHAR(60)  NULL,
  NM_BAIRRO        VARCHAR(80)  NOT NULL,
  NR_CEP           CHAR(8)      NOT NULL,
  NM_CIDADE        VARCHAR(80)  NOT NULL,
  SG_UF            CHAR(2)      NOT NULL,
  NR_TELEFONE      VARCHAR(11)  NOT NULL,
  DS_EMAIL         VARCHAR(120) NULL,
  DT_CONTRATACAO   DATE         NOT NULL,
  ID_PLANO         INT          NOT NULL,
  ID_RECEPCIONISTA INT          NOT NULL,
  ID_UNIDADE       INT          NOT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_ALUNO_CPF CHECK (NR_CPF REGEXP '^[0-9]{11}$'),
  CONSTRAINT CK_ALUNO_CEP CHECK (NR_CEP REGEXP '^[0-9]{8}$'),
  CONSTRAINT CK_ALUNO_TEL CHECK (CHAR_LENGTH(NR_TELEFONE) IN (10,11)),
  CONSTRAINT FK_ALUNO_PLANO FOREIGN KEY (ID_PLANO)
    REFERENCES PLANO (ID_PLANO) ON DELETE RESTRICT,
  CONSTRAINT FK_ALUNO_RECEP FOREIGN KEY (ID_RECEPCIONISTA)
    REFERENCES RECEPCIONISTA (ID_RECEPCIONISTA) ON DELETE RESTRICT,
  CONSTRAINT FK_ALUNO_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 5. SAÚDE
-- ---------------------------------------------------------------------
CREATE TABLE PRONTUARIO_SAUDE (
  ID_PRONTUARIO         INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO              INT        NOT NULL UNIQUE,
  IN_PROBLEMA_CARDIACO  TINYINT(1) NOT NULL DEFAULT 0,
  IN_PROBLEMA_OSSEO     TINYINT(1) NOT NULL DEFAULT 0,
  IN_PROBLEMA_RESPIR    TINYINT(1) NOT NULL DEFAULT 0,
  DS_OBSERVACAO         VARCHAR(255) NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRONT_ALUNO FOREIGN KEY (ID_ALUNO)
    REFERENCES ALUNO (ID_ALUNO) ON DELETE RESTRICT
);

CREATE TABLE PRONTUARIO_DOENCA (
  ID_PRONTUARIO INT          NOT NULL,
  NM_DOENCA     VARCHAR(100) NOT NULL,
  PRIMARY KEY (ID_PRONTUARIO, NM_DOENCA),
  CONSTRAINT FK_PDOENCA_PRONT FOREIGN KEY (ID_PRONTUARIO)
    REFERENCES PRONTUARIO_SAUDE (ID_PRONTUARIO) ON DELETE CASCADE
);

CREATE TABLE PRONTUARIO_MEDICAMENTO (
  ID_PRONTUARIO  INT          NOT NULL,
  NM_MEDICAMENTO VARCHAR(100) NOT NULL,
  PRIMARY KEY (ID_PRONTUARIO, NM_MEDICAMENTO),
  CONSTRAINT FK_PMED_PRONT FOREIGN KEY (ID_PRONTUARIO)
    REFERENCES PRONTUARIO_SAUDE (ID_PRONTUARIO) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- 6. AVALIAÇÃO FÍSICA
-- ---------------------------------------------------------------------
CREATE TABLE AVALIACAO_FISICA (
  ID_AVALIACAO        INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO            INT          NOT NULL,
  ID_INSTRUTOR        INT          NOT NULL,
  DT_AVALIACAO        DATE         NOT NULL,
  VL_PESO             DECIMAL(5,2) NOT NULL,
  PC_GORDURA_CORPORAL DECIMAL(5,2) NULL,
  NR_GORDURA_VISCERAL DECIMAL(5,2) NULL,
  PC_AGUA_CORPORAL    DECIMAL(5,2) NULL,
  VL_MASSA_MUSCULAR   DECIMAL(5,2) NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_AVAL_PESO CHECK (VL_PESO > 0),
  CONSTRAINT CK_AVAL_PC   CHECK ((PC_GORDURA_CORPORAL IS NULL OR PC_GORDURA_CORPORAL BETWEEN 0 AND 100)
                             AND (PC_AGUA_CORPORAL IS NULL OR PC_AGUA_CORPORAL BETWEEN 0 AND 100)),
  CONSTRAINT FK_AVAL_ALUNO FOREIGN KEY (ID_ALUNO)
    REFERENCES ALUNO (ID_ALUNO) ON DELETE RESTRICT,
  CONSTRAINT FK_AVAL_INSTR FOREIGN KEY (ID_INSTRUTOR)
    REFERENCES INSTRUTOR (ID_INSTRUTOR) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 7. EQUIPAMENTOS E EXERCÍCIOS
-- ---------------------------------------------------------------------
CREATE TABLE EQUIPAMENTO (
  ID_EQUIPAMENTO INT AUTO_INCREMENT PRIMARY KEY,
  NM_EQUIPAMENTO VARCHAR(100) NOT NULL UNIQUE,
  DS_EQUIPAMENTO VARCHAR(255) NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE TABLE EXERCICIO (
  ID_EXERCICIO    INT AUTO_INCREMENT PRIMARY KEY,
  NM_EXERCICIO    VARCHAR(100) NOT NULL UNIQUE,
  DS_EXERCICIO    VARCHAR(255) NULL,
  NM_GRUPO_MUSCULAR VARCHAR(50) NOT NULL,
  ID_EQUIPAMENTO  INT NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_EXERC_EQUIP FOREIGN KEY (ID_EQUIPAMENTO)
    REFERENCES EQUIPAMENTO (ID_EQUIPAMENTO) ON DELETE RESTRICT
);

CREATE TABLE UNIDADE_EQUIPAMENTO (
  ID_UNIDADE     INT NOT NULL,
  ID_EQUIPAMENTO INT NOT NULL,
  QT_EQUIPAMENTO INT NOT NULL,
  PRIMARY KEY (ID_UNIDADE, ID_EQUIPAMENTO),
  CONSTRAINT CK_UE_QT CHECK (QT_EQUIPAMENTO > 0),
  CONSTRAINT FK_UE_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT,
  CONSTRAINT FK_UE_EQUIP FOREIGN KEY (ID_EQUIPAMENTO)
    REFERENCES EQUIPAMENTO (ID_EQUIPAMENTO) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 8. TREINO (histórico por DT_INICIO/DT_FIM; alteração em colunas do treino)
-- ---------------------------------------------------------------------
CREATE TABLE TREINO (
  ID_TREINO            INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO             INT          NOT NULL,
  ID_INSTRUTOR         INT          NOT NULL,
  ID_INSTRUTOR_ALTEROU INT          NULL,
  DT_ALTERACAO         DATETIME     NULL,
  NM_TREINO            VARCHAR(100) NOT NULL,
  TP_TREINO            VARCHAR(50)  NULL,
  DS_TREINO            VARCHAR(255) NULL,
  DS_OBJETIVO          VARCHAR(150) NULL,
  DT_INICIO            DATE         NOT NULL,
  DT_FIM               DATE         NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_TREINO_DATAS CHECK (DT_FIM IS NULL OR DT_FIM >= DT_INICIO),
  CONSTRAINT FK_TREINO_ALUNO FOREIGN KEY (ID_ALUNO)
    REFERENCES ALUNO (ID_ALUNO) ON DELETE RESTRICT,
  CONSTRAINT FK_TREINO_INSTR FOREIGN KEY (ID_INSTRUTOR)
    REFERENCES INSTRUTOR (ID_INSTRUTOR) ON DELETE RESTRICT,
  CONSTRAINT FK_TREINO_INSTR_ALT FOREIGN KEY (ID_INSTRUTOR_ALTEROU)
    REFERENCES INSTRUTOR (ID_INSTRUTOR) ON DELETE RESTRICT
);

CREATE TABLE ITEM_TREINO (
  ID_ITEM          INT AUTO_INCREMENT PRIMARY KEY,
  ID_TREINO        INT          NOT NULL,
  ID_EXERCICIO     INT          NOT NULL,
  NM_DIA           VARCHAR(20)  NULL,
  QT_SERIES        TINYINT      NOT NULL,
  QT_REPETICOES    TINYINT      NOT NULL,
  VL_CARGA_KG      DECIMAL(6,2) NULL,
  NR_TEMPO_SEG     INT          NULL,
  NR_DESCANSO_SEG  INT          NULL,
  CONSTRAINT UQ_ITEM UNIQUE (ID_TREINO, ID_EXERCICIO),
  CONSTRAINT CK_ITEM_QT CHECK (QT_SERIES > 0 AND QT_REPETICOES > 0),
  CONSTRAINT FK_ITEM_TREINO FOREIGN KEY (ID_TREINO)
    REFERENCES TREINO (ID_TREINO) ON DELETE CASCADE,
  CONSTRAINT FK_ITEM_EXERC FOREIGN KEY (ID_EXERCICIO)
    REFERENCES EXERCICIO (ID_EXERCICIO) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 9. CHECK_IN
-- ---------------------------------------------------------------------
CREATE TABLE CHECK_IN (
  ID_CHECK_IN   BIGINT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO      INT          NOT NULL,
  ID_UNIDADE    INT          NOT NULL,
  DT_HR_ACESSO  DATETIME     NOT NULL,
  TP_ACESSO     VARCHAR(15)  NOT NULL,
  ST_ACESSO     VARCHAR(10)  NOT NULL,
  DS_MOTIVO_NEGADO VARCHAR(100) NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_CI_TIPO   CHECK (TP_ACESSO IN ('DIGITAL','FACIAL','APP_PARCEIRO')),
  CONSTRAINT CK_CI_STATUS CHECK (ST_ACESSO IN ('LIBERADO','NEGADO')),
  CONSTRAINT CK_CI_MOTIVO CHECK ((ST_ACESSO = 'NEGADO' AND DS_MOTIVO_NEGADO IS NOT NULL)
                              OR (ST_ACESSO = 'LIBERADO' AND DS_MOTIVO_NEGADO IS NULL)),
  CONSTRAINT FK_CI_ALUNO FOREIGN KEY (ID_ALUNO)
    REFERENCES ALUNO (ID_ALUNO) ON DELETE RESTRICT,
  CONSTRAINT FK_CI_UNIDADE FOREIGN KEY (ID_UNIDADE)
    REFERENCES UNIDADE (ID_UNIDADE) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- 10. PAGAMENTO
-- ---------------------------------------------------------------------
CREATE TABLE PAGAMENTO (
  ID_PAGAMENTO   INT AUTO_INCREMENT PRIMARY KEY,
  ID_ALUNO       INT           NOT NULL,
  DT_VENCIMENTO  DATE          NOT NULL,
  VL_PAGAMENTO   DECIMAL(10,2) NOT NULL,
  TP_FORMA       VARCHAR(10)   NOT NULL,
  ST_PAGAMENTO   VARCHAR(10)   NOT NULL,
  IN_RECORRENTE  TINYINT(1)    NOT NULL DEFAULT 1,
  DT_PAGAMENTO   DATE          NULL,
  DT_CRIACAO      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  DT_ATUALIZACAO  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT CK_PAG_VALOR  CHECK (VL_PAGAMENTO > 0),
  CONSTRAINT CK_PAG_FORMA  CHECK (TP_FORMA IN ('PIX','DEBITO','CREDITO')),
  CONSTRAINT CK_PAG_STATUS CHECK (ST_PAGAMENTO IN ('PENDENTE','PAGO','CANCELADO')),
  CONSTRAINT CK_PAG_DATA   CHECK ((ST_PAGAMENTO = 'PAGO' AND DT_PAGAMENTO IS NOT NULL)
                               OR (ST_PAGAMENTO <> 'PAGO')),
  CONSTRAINT FK_PAG_ALUNO FOREIGN KEY (ID_ALUNO)
    REFERENCES ALUNO (ID_ALUNO) ON DELETE RESTRICT
);

-- =====================================================================
-- ÍNDICES
-- =====================================================================
CREATE INDEX IX_CI_DATA ON CHECK_IN (ID_UNIDADE, DT_HR_ACESSO);
CREATE INDEX IX_PAG_STATUS ON PAGAMENTO (ST_PAGAMENTO, DT_VENCIMENTO);
CREATE INDEX IX_ALUNO_NOME    ON ALUNO (NM_ALUNO);
CREATE INDEX IX_ALUNO_EMAIL   ON ALUNO (DS_EMAIL);
CREATE INDEX IX_ALUNO_PLANO   ON ALUNO (ID_PLANO);
CREATE INDEX IX_ALUNO_UNIDADE ON ALUNO (ID_UNIDADE);
CREATE INDEX IX_PAG_ALUNO     ON PAGAMENTO (ID_ALUNO, DT_VENCIMENTO);
CREATE INDEX IX_CI_ALUNO      ON CHECK_IN (ID_ALUNO, DT_HR_ACESSO);
CREATE INDEX IX_AVAL_ALUNO    ON AVALIACAO_FISICA (ID_ALUNO, DT_AVALIACAO);
CREATE INDEX IX_TREINO_ALUNO  ON TREINO (ID_ALUNO, DT_FIM);

-- =====================================================================
-- MASSA DE DADOS (sintética)
-- =====================================================================

