-- =====================================================================
-- DML DE DEMONSTRAÇÃO (S01–S05, UPDATE, DELETE)
-- =====================================================================

-- S01 — Aluno com plano e unidade
SELECT a.ID_ALUNO, a.NM_ALUNO, p.NM_PLANO, u.NM_UNIDADE
FROM ALUNO a
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
JOIN UNIDADE u ON u.ID_UNIDADE = a.ID_UNIDADE
WHERE a.ID_ALUNO = 1;

-- S02 — Treino vigente e itens
SELECT t.NM_TREINO, e.NM_EXERCICIO, it.QT_SERIES, it.QT_REPETICOES, it.VL_CARGA_KG
FROM TREINO t
JOIN ITEM_TREINO it ON it.ID_TREINO = t.ID_TREINO
JOIN EXERCICIO e ON e.ID_EXERCICIO = it.ID_EXERCICIO
WHERE t.ID_ALUNO = 1 AND t.DT_FIM IS NULL;

-- S03 — Pagamentos do aluno
SELECT DT_VENCIMENTO, VL_PAGAMENTO, TP_FORMA, ST_PAGAMENTO, DT_PAGAMENTO
FROM PAGAMENTO WHERE ID_ALUNO = 1 ORDER BY DT_VENCIMENTO;

-- S04 — Check-ins recentes por unidade
SELECT c.DT_HR_ACESSO, a.NM_ALUNO, c.TP_ACESSO, c.ST_ACESSO
FROM CHECK_IN c JOIN ALUNO a ON a.ID_ALUNO = c.ID_ALUNO
WHERE c.ID_UNIDADE = 1
ORDER BY c.DT_HR_ACESSO DESC LIMIT 20;

-- S05 — Avaliação física mais recente
SELECT af.DT_AVALIACAO, af.VL_PESO, af.PC_GORDURA_CORPORAL, i.NM_INSTRUTOR
FROM AVALIACAO_FISICA af
JOIN INSTRUTOR i ON i.ID_INSTRUTOR = af.ID_INSTRUTOR
WHERE af.ID_ALUNO = 1
ORDER BY af.DT_AVALIACAO DESC LIMIT 1;

-- UPDATE exemplo: regularizar pagamento pendente do aluno 1 (se houver)
UPDATE PAGAMENTO
SET ST_PAGAMENTO = 'PAGO', DT_PAGAMENTO = CURRENT_DATE, TP_FORMA = 'PIX'
WHERE ID_ALUNO = 1 AND ST_PAGAMENTO = 'PENDENTE' AND DT_VENCIMENTO = '2026-10-10';

-- UPDATE exemplo: encerrar treino
UPDATE TREINO SET DT_FIM = CURRENT_DATE
WHERE ID_TREINO = (
  SELECT id FROM (SELECT ID_TREINO AS id FROM TREINO WHERE ID_ALUNO = 2 AND DT_FIM IS NULL ORDER BY ID_TREINO LIMIT 1) t
);

-- DELETE exemplo: remover item de treino órfão de demonstração (seguro se existir)
DELETE FROM ITEM_TREINO WHERE ID_ITEM = -1;
DELETE FROM PRONTUARIO_DOENCA WHERE ID_PRONTUARIO = -1 AND NM_DOENCA = 'INEXISTENTE';

-- =====================================================================
-- CONSULTAS GERENCIAIS G01–G13
-- =====================================================================

-- G01 — Acessos por hora e unidade (P1, K1)
SELECT u.NM_UNIDADE, HOUR(c.DT_HR_ACESSO) AS HORA, COUNT(*) AS QT_ACESSOS
FROM CHECK_IN c
JOIN UNIDADE u ON u.ID_UNIDADE = c.ID_UNIDADE
WHERE c.ST_ACESSO = 'LIBERADO'
GROUP BY u.NM_UNIDADE, HOUR(c.DT_HR_ACESSO)
ORDER BY u.NM_UNIDADE, HORA;

-- G02 — Acessos por dia da semana
SELECT u.NM_UNIDADE, DAYNAME(c.DT_HR_ACESSO) AS DIA_SEMANA, COUNT(*) AS QT_ACESSOS
FROM CHECK_IN c
JOIN UNIDADE u ON u.ID_UNIDADE = c.ID_UNIDADE
GROUP BY u.NM_UNIDADE, DAYNAME(c.DT_HR_ACESSO), DAYOFWEEK(c.DT_HR_ACESSO)
ORDER BY u.NM_UNIDADE, DAYOFWEEK(c.DT_HR_ACESSO);

-- G03 — Acessos negados por motivo (P1, K9)
SELECT u.NM_UNIDADE, c.DS_MOTIVO_NEGADO, COUNT(*) AS QT_NEGADOS
FROM CHECK_IN c
JOIN UNIDADE u ON u.ID_UNIDADE = c.ID_UNIDADE
WHERE c.ST_ACESSO = 'NEGADO'
GROUP BY u.NM_UNIDADE, c.DS_MOTIVO_NEGADO;

-- G04 — Média diária de acessos por unidade (K2)
SELECT u.NM_UNIDADE,
       COUNT(*) AS QT_TOTAL,
       COUNT(DISTINCT DATE(c.DT_HR_ACESSO)) AS QT_DIAS,
       ROUND(COUNT(*) / COUNT(DISTINCT DATE(c.DT_HR_ACESSO)), 1) AS MEDIA_DIARIA
FROM CHECK_IN c
JOIN UNIDADE u ON u.ID_UNIDADE = c.ID_UNIDADE
GROUP BY u.NM_UNIDADE;

-- G05 — Alunos com mensalidade em atraso (P2, K3)
SELECT a.ID_ALUNO, a.NM_ALUNO, p.NM_PLANO, pg.DT_VENCIMENTO, pg.VL_PAGAMENTO
FROM PAGAMENTO pg
JOIN ALUNO a ON a.ID_ALUNO = pg.ID_ALUNO
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
WHERE pg.ST_PAGAMENTO = 'PENDENTE' AND pg.DT_VENCIMENTO < CURRENT_DATE
ORDER BY pg.DT_VENCIMENTO;

-- G06 — Taxa de inadimplência (K4)
SELECT
  COUNT(*) AS QT_VENCIDAS,
  SUM(CASE WHEN ST_PAGAMENTO = 'PENDENTE' AND DT_VENCIMENTO < CURRENT_DATE THEN 1 ELSE 0 END) AS QT_EM_ATRASO,
  ROUND(100 * SUM(CASE WHEN ST_PAGAMENTO = 'PENDENTE' AND DT_VENCIMENTO < CURRENT_DATE THEN 1 ELSE 0 END) / COUNT(*), 2) AS TX_INADIMPLENCIA_PCT
FROM PAGAMENTO
WHERE DT_VENCIMENTO < CURRENT_DATE;

-- G07 — Formas de pagamento
SELECT TP_FORMA, ST_PAGAMENTO, COUNT(*) AS QT, ROUND(SUM(VL_PAGAMENTO), 2) AS TOTAL
FROM PAGAMENTO
GROUP BY TP_FORMA, ST_PAGAMENTO
ORDER BY TP_FORMA, ST_PAGAMENTO;

-- G08 — Receita recebida por mês e plano (K5)
SELECT DATE_FORMAT(pg.DT_PAGAMENTO, '%Y-%m') AS MES,
       p.NM_PLANO,
       ROUND(SUM(pg.VL_PAGAMENTO), 2) AS RECEITA
FROM PAGAMENTO pg
JOIN ALUNO a ON a.ID_ALUNO = pg.ID_ALUNO
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
WHERE pg.ST_PAGAMENTO = 'PAGO' AND pg.DT_PAGAMENTO IS NOT NULL
GROUP BY DATE_FORMAT(pg.DT_PAGAMENTO, '%Y-%m'), p.NM_PLANO
ORDER BY MES, p.NM_PLANO;

-- G09 — Conferência cadastral (P3)
SELECT a.ID_ALUNO, a.NM_ALUNO, a.NR_CPF, a.NM_BAIRRO, u.NM_UNIDADE, p.NM_PLANO,
       CASE WHEN ps.ID_PRONTUARIO IS NULL THEN 'SEM PRONTUARIO' ELSE 'OK' END AS PRONTUARIO
FROM ALUNO a
JOIN UNIDADE u ON u.ID_UNIDADE = a.ID_UNIDADE
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
LEFT JOIN PRONTUARIO_SAUDE ps ON ps.ID_ALUNO = a.ID_ALUNO
ORDER BY a.ID_ALUNO
LIMIT 50;

-- G10 — Alunos por plano (K6)
SELECT p.NM_PLANO, COUNT(*) AS QT_ALUNOS,
       ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM ALUNO), 1) AS PCT
FROM ALUNO a
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
GROUP BY p.NM_PLANO;

-- G11 — Alunos sem acesso em 14 dias (K7)
SELECT a.ID_ALUNO, a.NM_ALUNO, p.NM_PLANO, u.NM_UNIDADE
FROM ALUNO a
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
JOIN UNIDADE u ON u.ID_UNIDADE = a.ID_UNIDADE
WHERE NOT EXISTS (
  SELECT 1 FROM CHECK_IN c
  WHERE c.ID_ALUNO = a.ID_ALUNO
    AND c.DT_HR_ACESSO >= DATE_SUB(CURRENT_DATE, INTERVAL 14 DAY)
)
ORDER BY a.NM_ALUNO
LIMIT 30;

-- G12 — Treinos vigentes e avaliações por instrutor (K8)
SELECT i.NM_INSTRUTOR, u.NM_UNIDADE,
       SUM(CASE WHEN t.DT_FIM IS NULL THEN 1 ELSE 0 END) AS TREINOS_VIGENTES,
       COUNT(DISTINCT af.ID_AVALIACAO) AS QT_AVALIACOES
FROM INSTRUTOR i
JOIN UNIDADE u ON u.ID_UNIDADE = i.ID_UNIDADE
LEFT JOIN TREINO t ON t.ID_INSTRUTOR = i.ID_INSTRUTOR
LEFT JOIN AVALIACAO_FISICA af ON af.ID_INSTRUTOR = i.ID_INSTRUTOR
GROUP BY i.ID_INSTRUTOR, i.NM_INSTRUTOR, u.NM_UNIDADE;

-- G13 — Variação de peso entre primeira e última avaliação (K10)
SELECT a.ID_ALUNO, a.NM_ALUNO,
       MIN(af.DT_AVALIACAO) AS PRIMEIRA,
       MAX(af.DT_AVALIACAO) AS ULTIMA,
       (SELECT af2.VL_PESO FROM AVALIACAO_FISICA af2
         WHERE af2.ID_ALUNO = a.ID_ALUNO
         ORDER BY af2.DT_AVALIACAO ASC LIMIT 1) AS PESO_INICIAL,
       (SELECT af3.VL_PESO FROM AVALIACAO_FISICA af3
         WHERE af3.ID_ALUNO = a.ID_ALUNO
         ORDER BY af3.DT_AVALIACAO DESC LIMIT 1) AS PESO_FINAL
FROM ALUNO a
JOIN AVALIACAO_FISICA af ON af.ID_ALUNO = a.ID_ALUNO
GROUP BY a.ID_ALUNO, a.NM_ALUNO
HAVING COUNT(af.ID_AVALIACAO) >= 2
LIMIT 20;

-- G14 / RF21 — Visão única do aluno (P4)
SELECT a.NM_ALUNO, p.NM_PLANO, pg.DT_VENCIMENTO, pg.ST_PAGAMENTO,
       t.NM_TREINO, e.NM_EXERCICIO, it.QT_SERIES, it.QT_REPETICOES
FROM ALUNO a
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
LEFT JOIN PAGAMENTO pg ON pg.ID_ALUNO = a.ID_ALUNO
LEFT JOIN TREINO t ON t.ID_ALUNO = a.ID_ALUNO AND t.DT_FIM IS NULL
LEFT JOIN ITEM_TREINO it ON it.ID_TREINO = t.ID_TREINO
LEFT JOIN EXERCICIO e ON e.ID_EXERCICIO = it.ID_EXERCICIO
WHERE a.ID_ALUNO = 1;

-- =====================================================================
-- AUDITORIA A01–A06
-- =====================================================================

-- A01 — Aluno sem prontuário (RN07)
SELECT a.ID_ALUNO, a.NM_ALUNO
FROM ALUNO a
LEFT JOIN PRONTUARIO_SAUDE ps ON ps.ID_ALUNO = a.ID_ALUNO
WHERE ps.ID_PRONTUARIO IS NULL;

-- A02 — Treino sem itens (RN11)
SELECT t.ID_TREINO, t.ID_ALUNO, t.NM_TREINO
FROM TREINO t
LEFT JOIN ITEM_TREINO it ON it.ID_TREINO = t.ID_TREINO
WHERE it.ID_ITEM IS NULL;

-- A03 — Aluno com mais de um treino vigente (RN12)
SELECT t.ID_ALUNO, a.NM_ALUNO, COUNT(*) AS QT_VIGENTES
FROM TREINO t
JOIN ALUNO a ON a.ID_ALUNO = t.ID_ALUNO
WHERE t.DT_FIM IS NULL
GROUP BY t.ID_ALUNO, a.NM_ALUNO
HAVING COUNT(*) > 1;

-- A04 — RED em atraso com acesso liberado (RN16)
SELECT DISTINCT a.ID_ALUNO, a.NM_ALUNO, pg.DT_VENCIMENTO, c.DT_HR_ACESSO, c.ST_ACESSO
FROM ALUNO a
JOIN PLANO p ON p.ID_PLANO = a.ID_PLANO
JOIN PAGAMENTO pg ON pg.ID_ALUNO = a.ID_ALUNO
JOIN CHECK_IN c ON c.ID_ALUNO = a.ID_ALUNO
WHERE p.IN_BLOQUEIA_ATRASO = 1
  AND pg.ST_PAGAMENTO = 'PENDENTE'
  AND pg.DT_VENCIMENTO < CURRENT_DATE
  AND c.ST_ACESSO = 'LIBERADO';

-- A05 — Recorrente em forma diferente de crédito (RN18)
SELECT * FROM PAGAMENTO
WHERE IN_RECORRENTE = 1 AND TP_FORMA <> 'CREDITO';

-- A06 — Unidade sem gerente (RN22)
SELECT u.ID_UNIDADE, u.NM_UNIDADE
FROM UNIDADE u
LEFT JOIN GERENTE g ON g.ID_UNIDADE = u.ID_UNIDADE
WHERE g.ID_GERENTE IS NULL;
